def previous_one_swap(arr):
 answer=arr[:]
 for i in range(len(answer)-2,-1,-1):
  if answer[i]>answer[i+1]:
   j=len(answer)-1
   while answer[j]>=answer[i] or (j>i+1 and answer[j]==answer[j-1]):j-=1
   answer[i],answer[j]=answer[j],answer[i];break
 return answer

